command:
const actor = canvas.tokens.controlled[0]?.actor ?? game.user.character;
if (!actor) {
  ui.notifications.warn("Select a token or assign a character first.");
  return;
}

const result = await actor.toggleRollOption("all", "change-shape", null, true, "hybrid");
if (result === null) {
  ui.notifications.error("Could not find the Change Shape toggle on this character -- do they have the Werecreature Dedication feat (this module's patched version)?");
  return;
}

ui.notifications.info(`${actor.name} shifts to Hybrid form.`);

foundry.audio.AudioHelper.play({
  src: "modules/phil-pf2e-weredragon/assets/sounds/weredragon-hybrid.ogg",
  volume: 0.8,
  autoplay: true,
  loop: false,
}, true);

if (!actor.items.find((i) => i.type === "spell" && i.system.slug === "weredragon-breath-weapon")) {
  const source = await fromUuid("Compendium.phil-pf2e-weredragon.weredragon-feats.Item.WdrgnBreathSpl01");
  if (source) await actor.createEmbeddedDocuments("Item", [source.toObject()]);
}

const mod = game.modules.get("phil-pf2e-weredragon");
if (mod?.promptBizarreTransformation) await mod.promptBizarreTransformation(actor);
